class NomVariableGlobal extends BaseNomVariableGlobal {

    /**
     * Obtener un listado de los datos de las variables globales.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de las variables globales.
     */
    public static function obtenerListadoVariablesGlobales($inicio = 0, $limite = 10) {

        //Devolviendo el listado de variables globales en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->select('vg.idvariableglobal, vg.abreviatura, vg.denominacion, 
                    vg.idnivelconfiguracion, nc.denominacion as denomnivelconfiguracion, vg.abreviatura, 
                    vg.fechainicio, vg.fechafin, vg.descripcion, vg.lugaresdecimales')
                ->from('NomVariableGlobal vg')
                ->innerjoin('vg.NomNivelConfiguracion nc')
				->orderBy('vg.denominacion')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray():
                $query->select('vg.idvariableglobal, vg.abreviatura, vg.denominacion, 
                    vg.idnivelconfiguracion, nc.denominacion as denomnivelconfiguracion, vg.abreviatura, 
                    vg.fechainicio, vg.fechafin, vg.descripcion, vg.lugaresdecimales')
                ->from('NomVariableGlobal vg')
                ->innerjoin('vg.NomNivelConfiguracion nc')
				->orderBy('vg.denominacion')
                ->fetchArray();
        return $result;
    }

    /**
     * Obtener la cantidad total de variables globales.
     * 
     * @return int      Cantidad total de variables globales.
     */
    public static function obtenerCantidadTotalVariablesGlobales() {

        //Devolviendo la cantidad total de variables globales.
        return Doctrine_Query::create()->select('COUNT(idvariableglobal) AS cantidad')
                        ->from('NomVariableGlobal')
                        ->fetchOne()
                        ->cantidad;
    }
	
	/**
     * Obtener todas las variables globales.
     * 
     * @return array    Listado de los datos de las variables globales.
     */
	public static function obtenerTodasVariablesGlobal() {
        return Doctrine_Query::create()
                ->from('NomVariableGlobal')
				->where('fechafin is null or fechafin <= now()')
				->orderBy('denominacion')
                ->fetchArray();
    }
	
    /**
     * Obtener la variable global dado el identificador.
     * 
     * @param int $idvarglobal    Identificador de la variable global.
     * @return NomVariableGlobal  Objeto variable global (clase del dominio).
     */
    public static function obtenerObjVariableGlobalDadoId($idvarglobal) {
        return Doctrine::getTable('NomVariableGlobal')->find($idvarglobal);
    }
    
	/**
     * Obtener si existe una variable a partir de la denominaci�n y la abreviatura.
     * 
	 * @param int $idvar    		Identificador de la variable global.
	 * @param string $abrev    	 	Abreviatura de variable global.
     * @param string $denom    	 	Denominaci�n de variable global.
	 *
     * @return boolean    			Si existe la variable global.
     */
    public static function existeVariableGlobal($idvar, $abrev, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idvariableglobal) AS cantidad')
                        ->from('NomVariableGlobal');
		if($abrev){
			$query->addWhere("abreviatura ilike ?", $abrev);
		}
		if($denom){
			$query->addWhere("denominacion ilike ?", $denom);
		}				
		if($idvar){
			$query->addWhere('idvariableglobal <> ?', $idvar);
		}		
		
		return    $query->fetchOne()->cantidad;
     }
	 
	 
	 
	 
	
	
	
	
	
	
	
	
	
	
	
	
	
/***********************************VER DESDE AQUI**************************************************************/
	
    public static function existeDenominacionVariableGlobal($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomVariableGlobal p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
     
     public static function existeAbreviaturaVariableGlobal($abreviatura) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomVariableGlobal p')
                ->where("p.abreviatura=?", array($abreviatura))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
     
     public static function obtenerLugaresDecimalesXIdVariable($idvariableglobal) {
        return Doctrine_Query::create()->select('p.lugaresdecimales AS lugaresdecimales')
                        ->from('NomVariableGlobal p')
                        ->where('p.idvariableglobal = ?', array($idvariableglobal))
                        ->fetchOne()
                        ->lugaresdecimales;
   }

    public function findByIdOrDenom($denom, $idvariableglobal = null)
    {
        try {
            $query = Doctrine_Query::create();
            $query->from('NomVariableGlobal')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom'");
            if (!empty($idvariableglobal)) {
                $query->andWhere("idvariableglobal <> ?", $idvariableglobal);
            }
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }

}
